function normalizeImageFile(file,maxW=1600,maxH=1100,quality=.9){
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onerror=reject;
    reader.onload=()=>{
      const img=new Image();
      img.onerror=reject;
      img.onload=()=>{
        let w=img.naturalWidth||img.width, h=img.naturalHeight||img.height;
        const scale=Math.min(1,maxW/w,maxH/h);
        const nw=Math.max(1,Math.round(w*scale)), nh=Math.max(1,Math.round(h*scale));
        const c=document.createElement("canvas");
        c.width=nw;c.height=nh;
        const ctx=c.getContext("2d");
        ctx.fillStyle="#ffffff";
        ctx.fillRect(0,0,nw,nh);
        ctx.drawImage(img,0,0,nw,nh);
        resolve(c.toDataURL("image/jpeg",quality));
      };
      img.src=reader.result;
    };
    reader.readAsDataURL(file);
  });
}


function finishCodeFromReference(ref){
  const m=String(ref||"").match(/\.(BS|BB|BC)$/i);
  return m?m[1].toUpperCase():"";
}
function exactFinishLabel(p){
  const code=finishCodeFromReference(p.reference);
  return code ? `${code} · ${p.finish}` : p.finish;
}
function preferredImageFor(p){
  // Never silently show a catalogue image for a finish variant:
  // it could depict the wrong finish.
  if(p.manufacturerImage) return {src:p.manufacturerImage,source:"Site fabricant · finition exacte",quality:"exact"};
  if(p.manufacturerGenericImage) return {src:p.manufacturerGenericImage,source:"Site fabricant · visuel générique",quality:"generic"};
  return {src:"",source:"Photo fabricant à récupérer",quality:"missing"};
}
function useCatalogueFallback(productId){
  const p=state.selected.find(x=>x.id===productId);
  if(!p || !p.fallbackImage) return;
  p.image=p.fallbackImage;
  p.imageSource="Catalogue fabricant · visuel de secours";
  p.customImage=false;
  saveState();renderRooms();
}



async function autoCropForPdf(src){
  return new Promise((resolve)=>{
    const img=new Image();
    img.onload=()=>{
      try{
        const maxScan=1400;
        const scale=Math.min(1,maxScan/img.naturalWidth,maxScan/img.naturalHeight);
        const w=Math.max(1,Math.round(img.naturalWidth*scale));
        const h=Math.max(1,Math.round(img.naturalHeight*scale));
        const c=document.createElement("canvas"); c.width=w;c.height=h;
        const ctx=c.getContext("2d",{willReadFrequently:true});
        ctx.drawImage(img,0,0,w,h);
        const d=ctx.getImageData(0,0,w,h).data;
        let minX=w,minY=h,maxX=-1,maxY=-1;
        for(let y=0;y<h;y++){
          for(let x=0;x<w;x++){
            const i=(y*w+x)*4, a=d[i+3], r=d[i], g=d[i+1], b=d[i+2];
            // White/transparent background is ignored. Product + natural shadow are retained.
            const visible=a>18 && !(r>246 && g>246 && b>246);
            if(visible){
              if(x<minX)minX=x;if(x>maxX)maxX=x;
              if(y<minY)minY=y;if(y>maxY)maxY=y;
            }
          }
        }
        if(maxX<minX || maxY<minY){resolve(src);return;}
        const bw=maxX-minX+1,bh=maxY-minY+1;
        const pad=Math.round(Math.max(bw,bh)*0.055);
        minX=Math.max(0,minX-pad);minY=Math.max(0,minY-pad);
        maxX=Math.min(w-1,maxX+pad);maxY=Math.min(h-1,maxY+pad);
        const cw=maxX-minX+1,ch=maxY-minY+1;
        const out=document.createElement("canvas");
        // Keep enough resolution for A4 PDF output.
        const targetScale=Math.min(2.2,1800/Math.max(cw,ch));
        out.width=Math.max(1,Math.round(cw*targetScale));
        out.height=Math.max(1,Math.round(ch*targetScale));
        const o=out.getContext("2d");
        o.fillStyle="#ffffff";o.fillRect(0,0,out.width,out.height);
        o.drawImage(c,minX,minY,cw,ch,0,0,out.width,out.height);
        resolve(out.toDataURL("image/jpeg",0.94));
      }catch(e){resolve(src);}
    };
    img.onerror=()=>resolve(src);
    img.src=src;
  });
}

const manufacturerImageCache=JSON.parse(localStorage.getItem("hydropolis-manufacturer-v53")||"{}");
function manufacturerCacheKey(p){return `${p.manufacturer}|${p.reference}`;}
function saveManufacturerCache(){localStorage.setItem("hydropolis-manufacturer-v53",JSON.stringify(manufacturerImageCache));}
function cachedManufacturerImage(p){return manufacturerImageCache[manufacturerCacheKey(p)]||null;}

async function fetchManufacturerImage(p,force=false){
  const key=manufacturerCacheKey(p);
  if(!force && manufacturerImageCache[key]) return manufacturerImageCache[key];
  const r=await fetch("/api/manufacturer-image",{
    method:"POST",
    headers:{"Content-Type":"application/json"},
    body:JSON.stringify({
      manufacturerUrl:p.manufacturerUrl,
      reference:p.reference,
      finishCode:p.finishCode,
      finish:p.finish,
      designation:p.designation,
      originalDescription:p.originalDescription||"",
      collection:p.collection,
      manufacturer:p.manufacturer
    })
  });
  const data=await r.json();
  if(!r.ok) throw new Error(data.detail||data.error||"Recherche fabricant impossible");
  const hasImage=!!data.best;
  const src=hasImage
    ? (data.best.dataUrl ? data.best.dataUrl : `/api/image-proxy?url=${encodeURIComponent(data.best.url)}`)
    : "";
  const result={
    remoteUrl:data.best?.url||"",
    resolvedManufacturerUrl:data.manufacturerUrl||p.manufacturerUrl||"",
    src,
    finishMatch:data.best?.finishMatch||"",
    source:hasImage
      ?(data.best.finishMatch==="exact"
        ?`Site officiel fabricant · finition ${p.finish}`
        :"Site officiel fabricant · visuel produit générique")
      :"",
    note:data.note||"",
    drawingUrl:data.drawing?.url||"",
    drawingType:data.drawing?.type||"",
    drawingLabel:data.drawing?.label||"",
    technicalSheetUrl:data.technicalSheet?.url||"",
    technicalSheetLabel:data.technicalSheet?.label||"Fiche technique",
    technicalSheetType:data.technicalSheet?.type||"",
    installationGuideUrl:data.installationGuide?.url||"",
    installationGuideLabel:data.installationGuide?.label||"Notice d'installation",
    checkedAt:new Date().toISOString()
  };
  manufacturerImageCache[key]=result;
  saveManufacturerCache();
  return result;
}

function imageBadge(img,p){
  if(!img)return `Photo fabricant à rechercher`;
  return img.finishMatch==="exact"
    ?`✓ Photo officielle · ${p.finish}`
    :`Photo fabricant · finition non garantie`;
}

async function lookupCatalogPhoto(reference,button){
  const p=CATALOG.find(x=>x.reference===reference);
  if(!p)return;
  const card=button.closest(".result");
  const thumb=$(".catalog-thumb",card);
  const info=$(".photo-status",card);
  button.disabled=true;
  button.textContent="Recherche…";
  if(info)info.textContent="Interrogation du site fabricant…";
  try{
    const img=await fetchManufacturerImage(p,true);
    if(img.src){
      thumb.innerHTML=`<img src="${img.src}" alt="${p.reference}">`;
      if(info)info.innerHTML=`<b>${imageBadge(img,p)}</b>${img.note?`<br>${img.note}`:""}`;
      button.textContent="Actualiser la photo";
    }else{
      if(info)info.innerHTML=`Aucune photo officielle certifiée.${img.note?`<br>${img.note}`:""}${img.technicalSheetUrl?`<br><b>Fiche technique disponible.</b>`:""}`;
      button.textContent="Réessayer";
    }
    renderCatalog();
  }catch(e){
    if(info)info.textContent="Aucune photo officielle trouvée : "+e.message;
    button.textContent="Réessayer";
  }finally{
    button.disabled=false;
  }
}

async function enrichSelectedPhoto(id,force=false){
  const p=state.selected.find(x=>x.id===id);
  if(!p)return;
  p.imageStatus="Recherche sur le site fabricant…";
  renderRooms();
  try{
    const img=await fetchManufacturerImage(p,force);
    if(img.src){
      p.image=img.src;
      p.pdfImage=await autoCropForPdf(img.src);
      p.imageSource=img.source;
      p.imageFinishMatch=img.finishMatch;
      p.imageStatus=imageBadge(img,p);
      p.customImage=false;
    }else if(!p.image){
      p.imageStatus="Photo fabricant non certifiée";
    }
    p.imageNote=img.note;
    p.resolvedManufacturerUrl=img.resolvedManufacturerUrl||p.resolvedManufacturerUrl||p.manufacturerUrl||"";
    p.drawingUrl=img.drawingUrl||p.drawingUrl||"";
    p.drawingType=img.drawingType||p.drawingType||"";
    p.drawingLabel=img.drawingLabel||p.drawingLabel||"";
    p.technicalSheetUrl=img.technicalSheetUrl||p.technicalSheetUrl||"";
    p.technicalSheetLabel=img.technicalSheetLabel||p.technicalSheetLabel||"Fiche technique";
    p.installationGuideUrl=img.installationGuideUrl||p.installationGuideUrl||"";
    p.installationGuideLabel=img.installationGuideLabel||p.installationGuideLabel||"Notice d'installation";
    if(typeof p.includeDrawing!=="boolean") p.includeDrawing=false;
    if(typeof p.includeTechnicalSheet!=="boolean") p.includeTechnicalSheet=false;
    if(typeof p.includeInstallationGuide!=="boolean") p.includeInstallationGuide=false;
  }catch(e){
    p.imageStatus="Photo fabricant non trouvée";
    p.imageNote=e.message;
  }
  saveState();
  renderRooms();
}

function loadState(){
  try{let s=JSON.parse(localStorage.getItem("hydropolis-v21"));if(s)Object.assign(state,s)}catch(e){}
  if(!state.rooms?.length)state.rooms=[{id:"r1",title:"SDB MASTER",subtitle:"",manual:[]}];
  if(typeof state.showClientPrices!=="boolean")state.showClientPrices=true;
  if(typeof state.showSupplierReferences!=="boolean")state.showSupplierReferences=true;
}
function saveState(){localStorage.setItem("hydropolis-v21",JSON.stringify(state));}
function unique(k){return [...new Set(CATALOG.map(x=>x[k]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"fr"));}
function fillSelect(id,values,keepValue=true){
 const el=$("#"+id); if(!el)return;
 const previous=keepValue?el.value:"";
 const first=el.querySelector("option");
 const placeholder=first?first.cloneNode(true):new Option("Toutes","");
 el.innerHTML=""; el.appendChild(placeholder); placeholder.value="";
 values.filter(Boolean).sort((a,b)=>String(a).localeCompare(String(b),"fr",{sensitivity:"base"})).forEach(v=>{
   const o=document.createElement("option");o.value=v;o.textContent=v;el.appendChild(o);
 });
 if(previous && values.includes(previous)) el.value=previous; else el.value="";
}
function valuesFor(key,manufacturer=""){
 return [...new Set(CATALOG.filter(p=>!manufacturer||p.manufacturer===manufacturer).map(p=>p[key]).filter(Boolean))];
}
function updateDependentFilters(resetCollection=false){
 const manufacturer=$("#manufacturerFilter").value;
 fillSelect("collectionFilter",valuesFor("collection",manufacturer),!resetCollection);
 fillSelect("categoryFilter",valuesFor("category",manufacturer),true);
 fillSelect("finishFilter",valuesFor("finish",manufacturer),true);
}
function initFilters(){
 fillSelect("manufacturerFilter",valuesFor("manufacturer"),false);
 updateDependentFilters(false);
 $("#catalogCount").textContent=CATALOG.length+" références";
 $("#imageCount").textContent=new Set(CATALOG.filter(x=>x.image).map(x=>x.base)).size+" modèles avec photo fabricant";
}
function roomById(id){return state.rooms.find(r=>r.id===id)}
function renderRoomSelect(){let cur=$("#targetRoom")?.value||state.rooms[0].id;$("#targetRoom").innerHTML=state.rooms.map(r=>`<option value="${r.id}">${r.title}</option>`).join(""); if(state.rooms.some(r=>r.id===cur))$("#targetRoom").value=cur;}
function matches(p,q){let hay=[p.reference,p.base,p.designation,p.collection,p.manufacturer,p.finish,p.category].join(" ").toLowerCase();return q.toLowerCase().trim().split(/\s+/).filter(Boolean).every(w=>hay.includes(w));}
function renderCatalog(){
 let q=$("#searchInput").value, fs={manufacturer:$("#manufacturerFilter").value,collection:$("#collectionFilter").value,category:$("#categoryFilter").value,finish:$("#finishFilter").value};
 let rows=CATALOG.filter(p=>matches(p,q)&&Object.entries(fs).every(([k,v])=>!v||p[k]===v));
 $("#resultCount").textContent=rows.length+" résultat"+(rows.length>1?"s":"");
 let room=roomById($("#targetRoom").value)||state.rooms[0];
 $("#results").innerHTML=rows.slice(0,100).map(p=>{
   const cached=cachedManufacturerImage(p);
   return `<article class="result">
   <div class="catalog-thumb">${cached?`<img src="${cached.src}" alt="${p.reference}">`:`<div class="photo-missing"><b>Photo fabricant</b><br>${exactFinishLabel(p)}<br>à rechercher</div>`}</div>
   <div><div class="r-top"><span class="ref">${p.reference}</span><span class="badge">${p.manufacturer}</span><span class="badge">${p.collection}</span><span class="badge">${p.category}</span></div>
   <div class="designation">${p.designation}</div><div class="meta">${p.finish}</div>
   <div class="manufacturer-tools">
     <button class="tiny lookup-photo" data-ref="${p.reference}">${cached?"Actualiser la photo":"Trouver la photo fabricant"}</button>
     <a class="source-link" target="_blank" href="${cached?.resolvedManufacturerUrl||p.manufacturerUrl}">Fiche officielle ↗</a>
     ${cached?.technicalSheetUrl?`<a class="source-link technical-sheet-link" target="_blank" href="${cached.technicalSheetUrl}">Fiche technique ↗</a>`:""}
     ${cached?.drawingUrl?`<a class="source-link drawing-result-link" target="_blank" href="${cached.drawingUrl}">Drawing 2D ↗</a>`:""}
   </div>
   <div class="photo-status">${cached?`<b>${imageBadge(cached,p)}</b>${cached.note?`<br>${cached.note}`:""}`:`Priorité au site officiel du fabricant.`}</div>
   </div>
   <div class="price-box"><div class="price">${euro(p.totalPrice)} HT</div>
   ${p.internalReference?`<div class="internal">Ext. ${euro(p.price)} + ${p.internalReference} ${euro(p.internalPrice)}<br><b>interne ajouté automatiquement</b></div>`:`<div class="internal">Référence complète</div>`}
   <button class="btn primary add" data-ref="${p.reference}" style="margin-top:9px">Ajouter à ${room.title}</button></div>
 </article>`}).join("")||`<div class="empty">Aucun résultat.</div>`;
 $$(".add").forEach(b=>b.onclick=()=>addProduct(b.dataset.ref,$("#targetRoom").value));
 $$(".lookup-photo").forEach(b=>b.onclick=()=>lookupCatalogPhoto(b.dataset.ref,b));
}

function accessoryText(p){
  return [p.designation,p.marketingDescription,p.originalDescription,p.category,p.collection]
    .filter(Boolean).join(" ").toLowerCase();
}
function isBasinTap(p){
  if(!p || p.category!=="Lavabo") return false;
  const t=accessoryText(p);
  if(/bonde|waste|siphon|trap|vidage|accessoire|spare|replacement/.test(t)) return false;
  return /mitigeur|mélangeur|robinet|mixer|faucet|basin tap|bec lavabo|basin spout/.test(t);
}
function accessoryKind(p){
  const t=accessoryText(p);
  const spare=/replacement|spare|part of|body|locknut|rod|tube|sleeve|cap\b|vitone|deviatore/.test(t);
  if(spare) return "";
  if(/siphon|bottle trap/.test(t) && !/without trap/.test(t)) return "siphon";
  if(/bonde|basin waste|lavabo waste|waste/.test(t) && !/shower tray|bath|baignoire|without trap/.test(t)) return "bonde";
  return "";
}
function compatibleFinish(source,candidate){
  if(!source.finish) return true;
  if(candidate.finish===source.finish) return true;
  if(source.finishCode && candidate.finishCode && source.finishCode===candidate.finishCode) return true;
  return false;
}
function accessoryScore(source,candidate,kind){
  let score=0;
  if(candidate.manufacturer===source.manufacturer) score+=1000;
  if(compatibleFinish(source,candidate)) score+=500;
  else return -9999;
  if(accessoryKind(candidate)===kind) score+=300;
  if(candidate.collection===source.collection) score+=35;
  const t=accessoryText(candidate);
  if(kind==="siphon"){
    if(/siphon bouteille|bottle trap/.test(t)) score+=90;
    if(/lavabo|basin/.test(t)) score+=60;
  }
  if(kind==="bonde"){
    if(/bonde|basin waste|lavabo waste/.test(t)) score+=90;
    if(/clic.?clac|click.?clack|free flow|écoulement libre/.test(t)) score+=40;
    if(/lavabo|basin/.test(t)) score+=60;
  }
  if(candidate.price>0) score+=5;
  return score;
}
function matchingAccessory(source,kind){
  return CATALOG
    .filter(c=>c.reference!==source.reference && c.manufacturer===source.manufacturer && accessoryKind(c)===kind)
    .map(c=>({c,score:accessoryScore(source,c,kind)}))
    .filter(x=>x.score>0)
    .sort((x,y)=>y.score-x.score || String(x.c.reference).localeCompare(String(y.c.reference)))[0]?.c||null;
}
function basinAccessorySuggestions(p,roomId){
  if(!isBasinTap(p)) return "";
  const siphon=matchingAccessory(p,"siphon");
  const bonde=matchingAccessory(p,"bonde");
  const selectedRefs=new Set(state.selected.filter(x=>x.roomId===roomId).map(x=>x.reference));

  const option=(kind,item)=>{
    const label=kind==="siphon"?"Siphon assorti":"Bonde assortie";
    if(!item) return `<div class="accessory-option unavailable"><div><b>${label}</b><span>Aucune référence assortie identifiée dans le tarif ${p.manufacturer}.</span></div></div>`;
    const already=selectedRefs.has(item.reference);
    return `<div class="accessory-option">
      <div><b>${label}</b><span>${item.designation} · ${item.reference} · ${item.finish||p.finish}</span></div>
      <div class="accessory-option-right"><strong>${euro(item.totalPrice)} HT</strong>
      ${already?`<span class="accessory-added">Déjà ajouté</span>`:`<button class="tiny add-accessory" data-ref="${item.reference}" data-room="${roomId}" data-parent="${p.id}">+ Ajouter</button>`}</div>
    </div>`;
  };

  return `<div class="basin-accessories">
    <div class="basin-accessories-head"><b>Compléments lavabo assortis</b><span>Optionnels — même fabricant et même finition</span></div>
    ${option("siphon",siphon)}
    ${option("bonde",bonde)}
  </div>`;
}

